  // (2610/2619 active at difficulty>=3), see Dungeon-QuestCompanion-FG130 HellApcRunFG211.
  };
 internal static bool DeclaresApc(ushort dungeonId,ushort mapIdx){
  List<ushort[]> rows;
  if(!Table.TryGetValue(dungeonId,out rows))return false;
  foreach(ushort[] row in rows)if(row[0]==mapIdx)return true;
  return false;}
 internal static List<ushort[]> GetApcMonsters(ushort dungeonId,ushort mapIdx){
  List<ushort[]> rows;
  if(!Table.TryGetValue(dungeonId,out rows))return new List<ushort[]>();
  List<ushort[]> result=new List<ushort[]>();
  foreach(ushort[] row in rows)if(row[0]==mapIdx)result.Add(row);
  return result;}
}

